INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65933569', 65933569, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Penyunting Naskah Lampiran Pidato Presiden Tahun 2006', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 196200000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Lingkup kegiatan untuk Jasa Konsultansi Penyunting Naskah Lampid Tahun 2026, meliputi: 1. Penelaahan naskah Lampiran Pidato Presiden untuk memahami struktur, alur narasi, dan pesan utama yang akan disampaikan. 2. Penyuntingan redaksional dan kebahasaan, termasuk perbaikan tata bahasa, diksi, kejelasan kalimat, serta konsistensi gaya penulisan dan terminologi kebijakan. 3. Penyelarasan struktur dan narasi, memastikan capaian pembangunan dan tantangan pembangunan ke depan tersaji secara runtut, koheren, dan komunikatif. 4. Finalisasi naskah Lampiran Pidato Presiden, termasuk pemantapan berdasarkan masukan tim internal, sehingga siap digunakan dalam Pidato Kenegaraan Presiden RI.', 'Keluaran yang diharapkan dari kegiatan ini adalah Naskah Akhir Lampid Tahun 2026. Adapun keluaran yang akan dilaporkan pada setiap termin adalah sebagai berikut: No Periode Keluaran per Termin 1 Termin I Laporan antara yang memuat hasil identifikasi tren narasi politik, pendalaman isu strategis, serta penyusunan kerangka dan alur narasi Dokumen Lampiran Pidato Presiden sebagai dasar penyusunan naskah. 2 Termin II Laporan antara yang memuat hasil penelaahan substansi dan struktur naskah Lampiran Pidato Presiden, termasuk penyempurnaan alur narasi, konsistensi pesan kebijakan, serta kesesuaian dengan capaian pembangunan nasional. 3 Termin III Laporan akhir yang memuat naskah final Lampiran Pidato Presiden yang telah disunting dan siap digunakan dalam Pidato Kenegaraan Presiden RI.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2431909);
