INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65894776', 65894776, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Workshop Internasional WIS 2.0 Champion', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Keg', 'Maksud dari pengadaan jasa ini adalah untuk memastikan Workshop Internasional WIS 2.0 Champion yang dilaksanakan secara luring dapat berjalan sukses dan lancar, sesuai harapan Organisasi Meteorologi Dunia (WMO) dalam memfinalisasi kompetensi, kesiapan teknis mendalam, dan memperkuat sinergi anggota kelompok kerja WIS 2.0 Champions pasca on boarding daring. Tujuan pengadaan jasa ini adalah untuk merealisasikan keberhasilan workshop melalui dukungan operasional dan logistik yang komprehensif, meliputi penyediaan paket Full Day Meeting berkualitas di Hotel Holiday Inn Baruna Bali, penjaminan lingkungan pertemuan yang kondusif bebas kendala teknis, penyediaan 1 unit kendaraan siaga 24 jam, kelengkapan atribut acara dan Seminar Kit tepat guna, serta menghadirkan jamuan yang berkesan melalui welcome dinner yang syarat budaya dan keramahtamahan khas Indonesia.', 'Kegiatan ini dilaksanakan pada tanggal 30 Maret - 4 April 2026. Pelaksanaannya di Hotel Holidays Inn Bali Lingkup kegiatan pengadaan jasa ini mencakup penyediaan dukungan logistik dan operasional yang komprehensif, berdasarkan spesifikasi teknis dan kinerja yang telah ditetapkan, meliputi: 1. Paket Full Day Meeting 2. Seminar Kit 3. Transportasi Siaga: 5. Welcome Dinner: 6. Banner:', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2436523);
