INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65937303', 65937303, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Langganan Telepon dan Fax', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Timur (Kota)', 1800000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'Pengadaan layanan langganan telekomunikasi berupa sambungan telepon tetap/kantor dan layanan fax untuk menunjang komunikasi kedinasan Biro Humas Kementerian Ketenagakerjaan dengan pemangku kepentingan, unit internal, serta masyarakat. Ruang lingkup meliputi penyediaan/aktivasi nomor telepon (dan/atau trunk/saluran), penyediaan layanan fax (analog dan/atau fax-to-email), pemeliharaan layanan selama masa kontrak, dukungan teknis (helpdesk dan perbaikan gangguan), serta penyediaan tagihan bulanan yang terperinci untuk proses verifikasi dan pembayaran. Layanan dilaksanakan selama 12 (dua belas) bulan atau sesuai periode yang ditetapkan dalam RUP/kontrak, dengan mekanisme pembayaran berdasarkan layanan bulan berjalan setelah diverifikasi.', 'Penyedia menyediakan layanan langganan telepon kantor dan fax untuk mendukung komunikasi kedinasan Biro Humas Kemnaker selama masa kontrak (12 bulan atau sesuai periode RUP), meliputi aktivasi/penyediaan sambungan telepon tetap (PSTN/VoIP sesuai ketersediaan jaringan) dan layanan fax (analog dan/atau fax-to-email) dengan jumlah nomor/line/titik layanan sesuai kebutuhan satker; layanan wajib berfungsi stabil, menyediakan fitur minimum caller ID serta dukungan pengalihan/pembatasan panggilan bila diperlukan, dan untuk fax menyediakan kemampuan kirim–terima beserta bukti/log (khusus e-fax); penyedia wajib memberikan dukungan teknis/helpdesk, penanganan gangguan dengan waktu respons maksimal 2 jam pada hari kerja dan pemulihan maksimal 1x24 jam (kecuali force majeure/pemeliharaan terjadwal), serta menyampaikan tagihan bulanan yang terinci (biaya langganan, pemakaian bila ada, pajak, periode layanan, dan identitas nomor/akun) sebagai dasar verifikasi layanan bulan berjalan sebelum pembayaran dilakukan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2436595);
