INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65938877', 65938877, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Sewa Mesin Fotokopi Digital', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 UB', 'Penyediaan layanan sewa unit mesin fotokopi digital multifungsi untuk mendukung kelancaran operasional perkantoran Biro Humas, mencakup pengiriman dan instalasi di lokasi, penyiapan konektivitas/jaringan (bila diperlukan), layanan pemeliharaan berkala dan perbaikan selama masa sewa, penggantian suku cadang yang aus/rusak, penyediaan bahan habis pakai terkait operasional mesin (mis. toner/drum) sesuai ketentuan kontrak (kertas dikecualikan), pencatatan/rekapitulasi meter counter serta pelaporan bulanan, layanan helpdesk/call service dengan waktu respons yang disepakati, penyediaan unit pengganti apabila unit utama tidak dapat beroperasi, serta penarikan kembali unit pada akhir masa sewa', 'Mesin yang disewa minimal berjenis digital multifunction (copy/print/scan) ukuran kertas hingga A3 (mendukung A4/F4), kecepatan cetak/salin minimal 25–30 halaman per menit, resolusi minimal 600×600 dpi, fitur duplex (cetak bolak-balik) otomatis, ADF (automatic document feeder) untuk pemindaian/penyalinan multi-lembar, konektivitas minimal USB dan LAN (mendukung printing jaringan), fitur scan to folder/email (atau setara), kompatibel dengan OS kantor yang umum digunakan, memiliki pengaturan penghematan (eco mode) dan keamanan dasar (mis. PIN/secure print bila tersedia), serta mampu beroperasi stabil pada beban kerja kantor (duty cycle bulanan menyesuaikan kebutuhan); layanan termasuk instalasi & konfigurasi, maintenance preventif, perbaikan korektif, ketersediaan suku cadang dan consumables mesin (toner/drum/developer) sesuai kebutuhan, SLA layanan minimal waktu respons maksimal 1×24 jam pada hari kerja dan penggantian unit apabila gangguan berulang/berkepanjangan, serta mekanisme pencatatan counter untuk dasar monitoring pemakaian dan administrasi pembayaran sesuai kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2437165);
