INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65938757', 65938757, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Langganan Capcut', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Selatan (Kota)', 3600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'Pekerjaan ini merupakan pengadaan langganan aplikasi pengeditan video CapCut (lisensi resmi/berlangganan) untuk mendukung produksi konten komunikasi publik Biro Humas Kementerian Ketenagakerjaan, meliputi akses penggunaan aplikasi selama masa langganan untuk kebutuhan pembuatan, penyuntingan, dan finalisasi materi video (mis. reels/short video, konten edukasi, dokumentasi kegiatan, dan materi kampanye), termasuk pengelolaan akun sesuai kebutuhan unit kerja, pembaruan versi aplikasi selama periode berlangganan, serta dukungan layanan/administrasi berlangganan agar proses produksi konten berjalan efektif, terstandar, dan berkelanjutan.', 'Penyediaan lisensi berlangganan CapCut (paket berbayar yang legal dan aktif) untuk jumlah akun sesuai kebutuhan, kompatibel minimal pada perangkat kerja yang digunakan unit (desktop/laptop dan/atau perangkat mobile) dengan fitur utama tanpa watermark, akses template/efek/asset kreatif, fasilitas ekspor video kualitas tinggi (minimal Full HD dan mendukung format umum MP4/MOV), fitur pengolahan audio dan teks/caption (termasuk auto-caption bila tersedia), serta dukungan penyimpanan/proyek (lokal dan/atau cloud) dan kolaborasi/berbagi proyek bila menggunakan paket tim; langganan mencakup masa berlaku sesuai periode kebutuhan (mis. tahunan), mekanisme aktivasi–deaktivasi akun oleh admin, serta layanan bantuan/dukungan teknis dan bukti lisensi/invoice yang sah untuk kebutuhan administrasi pertanggungjawaban anggaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2438699);
